insert into public.kb_documents (title, kind, content) values
  ('О компании', 'company',
   'Аалам Хаус — агентство аренды недвижимости в Кыргызстане. Главное направление — Иссык-Куль: северный берег (Чолпон-Ата, Бостери, Кара-Ой, Чок-Тал) и южный берег (Тосор, Жети-Огуз, Каракол). Также работаем в Бишкеке, Оше, Нарыне и Джалал-Абаде — в основном квартиры и офисы на длительный срок.
Мы сами осматриваем каждый объект, фотографируем его как есть и называем честную цену. Работаем по прозрачному договору без скрытых платежей. Поддержка 24/7 в течение проживания.
Как мы работаем: 1) заявка — гость рассказывает о датах, бюджете и пожеланиях; 2) подбор — предлагаем 3–5 проверенных вариантов с фото; 3) просмотр — показываем объект лично или по видеозвонку; 4) договор и заселение.'),
  ('Залог', 'faq', 'Вопрос: Какой залог нужен?
Ответ: Обычно сумма в размере одних суток (посуточная аренда) или одного месяца (долгосрочная аренда). Точные условия указаны в договоре.'),
  ('Проживание с животными', 'faq', 'Вопрос: Можно ли с животными?
Ответ: Есть объекты, где можно жить с животными. Нужно указать это в заявке, и менеджер подберёт подходящие варианты.'),
  ('Когда бронировать Иссык-Куль', 'faq', 'Вопрос: Когда лучше бронировать жильё на Иссык-Куле?
Ответ: На июль и август — за 2–3 месяца. В остальные сезоны хватает нескольких недель.'),
  ('Как сдать своё жильё', 'faq', 'Вопрос: Как сдать своё жильё через Аалам Хаус?
Ответ: Оставьте заявку. Мы оценим объект, сделаем фото и найдём арендаторов. Берём на себя заселение и контроль состояния жилья.'),
  ('Оплата', 'policy', 'Вопрос: Как оплатить?
Ответ: Наличными, переводом на карту или по счёту для компаний. Предоплата — 30% при бронировании.'),
  ('Отмена бронирования', 'policy', 'Вопрос: Можно ли отменить бронь?
Ответ: Да. При отмене за 14 дней до заезда и раньше предоплата возвращается полностью. При более поздней отмене — по условиям конкретного объекта.'),
  ('Трансфер и экскурсии', 'service', 'Аалам Хаус организует трансфер: встретим в аэропорту или на автовокзале, отвезём до объекта. Помогаем с экскурсиями по окрестностям Иссык-Куля, например в ущелье Жети-Огуз. Стоимость трансфера рассчитывает менеджер под маршрут.');
